import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"Server environment","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md"}'),r={name:"reference/environment.md"};function n(s,e,c,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="server-environment" tabindex="-1">Server environment <a class="header-anchor" href="#server-environment" aria-label="Permalink to &quot;Server environment&quot;">​</a></h1><p>The server reads its configuration from its environment. When a value is wrong, it stops at start and names the invalid variables, never their values.</p><h2 id="installation-settings" tabindex="-1">Installation settings <a class="header-anchor" href="#installation-settings" aria-label="Permalink to &quot;Installation settings&quot;">​</a></h2><p>An installation keeps its settings in <code>.env</code>, in its directory (mode <code>0600</code>). The installer and <code>wake-server</code> manage the <code>WAKE_</code> lines that hold the version, the address, the ports and the generated secrets (such as <code>WAKE_VERSION</code>, <code>WAKE_PUBLIC_URL</code> and <code>WAKE_POSTGRES_PASSWORD</code>); leave those as they are. The lines below are the ones you may add or change. After a change, run <code>wake-server start</code>, which recreates the services with it; upgrades keep <code>.env</code>.</p><p>Besides the managed lines, only these have an effect. The other <a href="#server">server variables</a>, such as <code>WAKE_LOG_LEVEL</code> or <code>DATABASE_POOL_SIZE</code>, cannot be set in an installation: the installation sets the ones it needs itself and leaves the rest at their defaults.</p><table tabindex="0"><thead><tr><th>Line</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>WAKE_UPGRADE_BACKUPS</code></td><td><code>1</code></td><td>How many upgrade backups a healthy upgrade keeps, a whole number from 1 to 100; any other value keeps every backup. Read at the next upgrade: no <code>wake-server start</code> needed. See <a href="/wake-dist/docs/run/upgrade#upgrade-backups-kept">Upgrade backups kept</a></td></tr><tr><td><code>WAKE_UPDATE_CHECK</code></td><td><code>on</code></td><td><code>off</code> stops the server&#39;s <a href="/wake-dist/docs/run/upgrade#how-you-hear-of-a-new-release">update check</a> (the server&#39;s <code>UPDATE_CHECK</code>)</td></tr><tr><td><code>SIGN_UP</code></td><td><code>open</code></td><td><code>invitation</code> lets only people with an invitation create accounts. See <a href="/wake-dist/docs/run/sign-up">Sign-up and accounts</a></td></tr><tr><td><code>SETUP_TOKEN</code></td><td></td><td>While the server has no account, only a password sign-up carrying this token creates the first one. A domain install writes it. See <a href="/wake-dist/docs/run/sign-up#the-first-account">The first account</a></td></tr><tr><td><code>GITHUB_CLIENT_ID</code>, <code>GITHUB_CLIENT_SECRET</code></td><td></td><td>Turn on GitHub sign-in</td></tr><tr><td><code>GOOGLE_CLIENT_ID</code>, <code>GOOGLE_CLIENT_SECRET</code></td><td></td><td>Turn on Google sign-in</td></tr><tr><td><code>MICROSOFT_CLIENT_ID</code>, <code>MICROSOFT_CLIENT_SECRET</code></td><td></td><td>Turn on Microsoft sign-in</td></tr><tr><td><code>OIDC_ISSUER</code>, <code>OIDC_CLIENT_ID</code>, <code>OIDC_CLIENT_SECRET</code>, <code>OIDC_NAME</code></td><td></td><td>Turn on an OpenID Connect provider</td></tr></tbody></table><p>The provider lines mean what they mean for the server, below; an empty value counts as unset. See <a href="/wake-dist/docs/run/sign-in-providers">Sign-in providers</a>.</p><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h2><p>The variables of the <code>wake-server</code> image, for a server you <a href="/wake-dist/docs/run/images">run yourself</a>. An installation sets them itself, from the <code>.env</code> lines above.</p><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>yes</td><td></td><td>Postgres connection string</td></tr><tr><td><code>DATABASE_POOL_SIZE</code></td><td>no</td><td><code>10</code></td><td>Most database connections the server opens, 1 to 100</td></tr><tr><td><code>DATABASE_CONNECT_TIMEOUT_MS</code></td><td>no</td><td><code>5000</code></td><td>How long a request waits for a free connection, 100 to 60000; past it the request answers <code>503</code> <code>service_unavailable</code> with <code>Retry-After: 5</code></td></tr><tr><td><code>DATABASE_STATEMENT_TIMEOUT_MS</code></td><td>no</td><td><code>30000</code></td><td>Longest a statement runs before the database cancels it (the request answers <code>503</code> <code>service_unavailable</code>), 1000 to 600000; migrations are not limited. A session idle inside a transaction is ended after 60 s</td></tr><tr><td><code>MIGRATE_ON_START</code></td><td>no</td><td><code>true</code></td><td>Apply pending migrations at start. See <a href="/wake-dist/docs/run/images#migrations">Migrations</a></td></tr><tr><td><code>WAKE_STREAM_CACHE_PROJECTS</code></td><td>no</td><td><code>16</code></td><td>Replayed projects each of the server&#39;s two stream caches keeps in memory, least recently used first out, 0 to 1000; <code>0</code> turns both caches off, so every load replays the whole project</td></tr></tbody></table><h3 id="address-and-proxy" tabindex="-1">Address and proxy <a class="header-anchor" href="#address-and-proxy" aria-label="Permalink to &quot;Address and proxy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PUBLIC_URL</code></td><td>yes</td><td></td><td>The server&#39;s public origin; the OAuth issuer and the MCP resource derive from it</td></tr><tr><td><code>PORT</code></td><td>no</td><td><code>3000</code></td><td>Listening port</td></tr><tr><td><code>WEB_ORIGINS</code></td><td>no</td><td>none</td><td>Comma-separated browser origins allowed by the CORS and CSRF checks</td></tr><tr><td><code>WEB_APP_URL</code></td><td>no</td><td><code>PUBLIC_URL</code></td><td>Where a provider sign-in returns the browser without a valid return target, the device approval page <code>wake login</code> opens (<code>/device</code> there) and the base of invitation links (<code>/invite#...</code> there)</td></tr><tr><td><code>COOKIE_SECURE</code></td><td>no</td><td><code>true</code></td><td>A <code>__Host-</code> secure session cookie; <code>false</code> only for plain-http local use</td></tr><tr><td><code>TRUST_PROXY</code></td><td>no</td><td><code>false</code></td><td>Read client addresses from <code>X-Forwarded-For</code>; only behind your own proxy</td></tr><tr><td><code>TRUSTED_PROXY_HOPS</code></td><td>no</td><td><code>1</code></td><td>With <code>TRUST_PROXY</code>, how many proxies append to <code>X-Forwarded-For</code>, 1 to 10; the client is that many entries from the right</td></tr></tbody></table><h3 id="sign-up-and-sign-in" tabindex="-1">Sign-up and sign-in <a class="header-anchor" href="#sign-up-and-sign-in" aria-label="Permalink to &quot;Sign-up and sign-in&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>SIGN_UP</code></td><td>no</td><td><code>open</code></td><td>Who creates accounts: <code>open</code> lets anyone sign up; <code>invitation</code> lets only people with a pending invitation, and the server&#39;s first account, create one, by password or through any provider (only by password, with the token, when <code>SETUP_TOKEN</code> is set). Any other value stops start-up. See <a href="/wake-dist/docs/run/sign-up">Sign-up and accounts</a></td></tr><tr><td><code>SETUP_TOKEN</code></td><td>no</td><td></td><td>While the server has no account, only a password sign-up carrying this token (the <code>setup</code> value of the sign-up link a domain install prints) creates the first one; a provider sign-in cannot. 32 to 256 characters; a shorter value stops start-up. No effect once an account exists. See <a href="/wake-dist/docs/run/sign-up">Sign-up and accounts</a></td></tr><tr><td><code>OAUTH_MAX_UNUSED_CLIENTS</code></td><td>no</td><td><code>10000</code></td><td>Dynamically registered OAuth clients without a grant before registration pauses, 1 to 1000000; unused ones expire after a day</td></tr></tbody></table><h3 id="sign-in-providers" tabindex="-1">Sign-in providers <a class="header-anchor" href="#sign-in-providers" aria-label="Permalink to &quot;Sign-in providers&quot;">​</a></h3><p>Each group turns one provider on: set all of its variables or none. The callback is <code>&lt;PUBLIC_URL&gt;/v1/auth/&lt;provider&gt;/callback</code>. See <a href="/wake-dist/docs/run/sign-in-providers">Sign-in providers</a>.</p><table tabindex="0"><thead><tr><th>Variables</th><th>Provider</th></tr></thead><tbody><tr><td><code>GITHUB_CLIENT_ID</code>, <code>GITHUB_CLIENT_SECRET</code></td><td>GitHub</td></tr><tr><td><code>GOOGLE_CLIENT_ID</code>, <code>GOOGLE_CLIENT_SECRET</code></td><td>Google</td></tr><tr><td><code>MICROSOFT_CLIENT_ID</code>, <code>MICROSOFT_CLIENT_SECRET</code></td><td>Microsoft work, school and personal accounts</td></tr><tr><td><code>OIDC_ISSUER</code>, <code>OIDC_CLIENT_ID</code>, <code>OIDC_CLIENT_SECRET</code>, <code>OIDC_NAME</code></td><td>One OpenID Connect provider. <code>OIDC_ISSUER</code> is its issuer URL, <code>https</code> (<code>http</code> only on <code>localhost</code>) without a query or fragment; <code>OIDC_NAME</code> is the button&#39;s text, 1 to 40 characters without control characters</td></tr></tbody></table><h3 id="evidence-storage" tabindex="-1">Evidence storage <a class="header-anchor" href="#evidence-storage" aria-label="Permalink to &quot;Evidence storage&quot;">​</a></h3><p>Evidence file storage on S3, R2 or MinIO. Set the first four together, or none: without them the server starts, and uploads answer <code>evidence_storage_unavailable</code>. See <a href="/wake-dist/docs/run/evidence-storage">Evidence storage</a>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>EVIDENCE_S3_ENDPOINT</code></td><td>no</td><td></td><td>The origin browsers and agents reach: presigned addresses point there</td></tr><tr><td><code>EVIDENCE_S3_BUCKET</code></td><td>no</td><td></td><td>The bucket, which must exist</td></tr><tr><td><code>EVIDENCE_S3_ACCESS_KEY_ID</code></td><td>no</td><td></td><td>The server&#39;s key, limited to the bucket</td></tr><tr><td><code>EVIDENCE_S3_SECRET_ACCESS_KEY</code></td><td>no</td><td></td><td>Its secret</td></tr><tr><td><code>EVIDENCE_S3_INTERNAL_ENDPOINT</code></td><td>no</td><td><code>EVIDENCE_S3_ENDPOINT</code></td><td>How the server itself reaches the storage, such as <code>http://minio:9000</code> inside a private network; a request that takes longer than 10 s is abandoned and the confirmation answers <code>evidence_storage_unavailable</code></td></tr><tr><td><code>EVIDENCE_S3_REGION</code></td><td>no</td><td><code>us-east-1</code></td><td>Signing region (<code>auto</code> for R2)</td></tr><tr><td><code>EVIDENCE_S3_PATH_STYLE</code></td><td>no</td><td><code>true</code></td><td>Bucket in the path; <code>false</code> puts the bucket in the host name</td></tr></tbody></table><h3 id="updates-and-logs" tabindex="-1">Updates and logs <a class="header-anchor" href="#updates-and-logs" aria-label="Permalink to &quot;Updates and logs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>UPDATE_CHECK</code></td><td>no</td><td><code>on</code></td><td><code>on</code> reads the newest stable release from GitHub at start and every 12 hours and serves it at <code>GET /v1/updates</code>; <code>off</code> makes no request. Any other value stops start-up. See <a href="/wake-dist/docs/run/upgrade#how-you-hear-of-a-new-release">How you hear of a new release</a></td></tr><tr><td><code>UPDATE_CHECK_REPOSITORY</code></td><td>no</td><td><code>dalodev/wake-dist</code></td><td>The GitHub repository (<code>owner/repo</code>) whose releases the check reads</td></tr><tr><td><code>WAKE_LOG_LEVEL</code></td><td>no</td><td><code>info</code></td><td>Least severe log line written: <code>info</code>, <code>warn</code> or <code>error</code>; empty means <code>info</code>. Any other value stops start-up. See <a href="/wake-dist/docs/run/logs">Logs</a></td></tr></tbody></table><h2 id="web-container" tabindex="-1">Web container <a class="header-anchor" href="#web-container" aria-label="Permalink to &quot;Web container&quot;">​</a></h2><p>The <code>wake-web</code> image needs two variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>WAKE_API_PROXY</code></td><td>yes</td><td></td><td>The server&#39;s address on your internal network, such as <code>http://wake-server:3000</code>; <code>/v1</code> is forwarded there</td></tr><tr><td><code>WAKE_S3_URL</code></td><td>when evidence is stored</td><td>none</td><td>The evidence storage address browsers download from, the server&#39;s <code>EVIDENCE_S3_ENDPOINT</code>; its origin joins the page&#39;s policy for images. A value that is not an <code>http(s)</code> URL stops the container</td></tr></tbody></table><p>The web container answers any <code>Host</code>; your proxy decides which names reach it.</p>',27)])])}const E=t(r,[["render",n]]);export{p as __pageData,E as default};
